package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigInteger;
import java.nio.ByteBuffer;
import java.util.*;
import org.apache.commons.compress.archivers.zip.ZipEncoding;
import org.apache.commons.compress.archivers.zip.ZipEncodingHelper;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.fail;

public class TarUtils_parseOctal_TriageGen0Test {

    @Test
    public void testParseOctal_ValidSimple() {
        byte[] buffer = "000123".getBytes();
        long result = TarUtils.parseOctal(buffer, 0, 6);
        assertEquals(83L, result); // 123 in octal is 1*64 + 2*8 + 3 = 83
    }

    @Test
    public void testParseOctal_WithLeadingSpaces() {
        byte[] buffer = "   0755".getBytes();
        long result = TarUtils.parseOctal(buffer, 0, 8);
        assertEquals(493L, result); // 755 octal = 493 decimal
    }

    @Test
    public void testParseOctal_WithTrailingSpacesAndNuls() {
        byte[] buffer = "0123  \0\0".getBytes();
        // length is 8: '0','1','2','3',' ',' ','\0','\0'
        long result = TarUtils.parseOctal(buffer, 0, 8);
        assertEquals(83L, result);
    }

    @Test
    public void testParseOctal_FirstByteZero() {
        byte[] buffer = {0, 1, 2, 3};
        long result = TarUtils.parseOctal(buffer, 0, 4);
        assertEquals(0L, result);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_LengthTooSmall() {
        byte[] buffer = "0".getBytes();
        TarUtils.parseOctal(buffer, 0, 1);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_InvalidOctalDigit() {
        byte[] buffer = "0128".getBytes(); // '8' is invalid
        TarUtils.parseOctal(buffer, 0, 4);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_InvalidNonNumeric() {
        byte[] buffer = "012A".getBytes();
        TarUtils.parseOctal(buffer, 0, 4);
    }

    @Test
    public void testParseOctal_WithInternalNull() {
        // The loop breaks when it encounters a 0
        byte[] buffer = {'0', '1', 0, '2', '3'};
        long result = TarUtils.parseOctal(buffer, 0, 5);
        assertEquals(1L, result);
    }

    @Test
    public void testParseOctal_OffsetUsage() {
        byte[] buffer = {'X', ' ', '0', '1', '0'};
        // offset 2, length 3 -> "010"
        long result = TarUtils.parseOctal(buffer, 2, 3);
        assertEquals(8L, result);
    }

    @Test
    public void testParseOctal_LargeValue() {
        // Test max long-ish octal
        byte[] buffer = "777777777777".getBytes();
        long result = TarUtils.parseOctal(buffer, 0, 12);
        // 8^12 - 1 is not quite right for logic, let's just verify it calculates
        long expected = 0;
        for (int i = 0; i < 12; i++) {
            expected = (expected << 3) + 7;
        }
        assertEquals(expected, result);
    }

    @Test
    public void testParseOctal_TrailingSpaceOnly() {
        byte[] buffer = {'0', '1', ' ', ' '};
        long result = TarUtils.parseOctal(buffer, 0, 4);
        assertEquals(1L, result);
    }

    @Test
    public void testParseOctal_AllSpaces() {
        // If all are spaces, start will eventually equal end
        byte[] buffer = {' ', ' ', ' ', ' '};
        long result = TarUtils.parseOctal(buffer, 0, 4);
        assertEquals(0L, result);
    }

    @Test
    public void testParseOctal_SingleDigitWithLengthTwo() {
        // Requirement is length >= 2
        byte[] buffer = {'0', '7'};
        long result = TarUtils.parseOctal(buffer, 0, 2);
        assertEquals(7L, result);
    }
}
